{"file_path":"tests/test_spec.py","content":"import pytest

from sales_dashboard.loader import (
    daily_conversion_counts,
    dedupe_sessions,
    parse_session_log,
)
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def session(id_, day, converted):
    return {"id": id_, "day": day, "converted": converted}


def test_conversion_rate_none_counts_in_denominator():
    assert conversion_rate([session("a", 1, True), session("b", 1, None)]) == 0.5
    assert conversion_rate([session("a", 1, None), session("b", 1, False)]) == 0.0
    assert conversion_rate([]) == 0.0


def test_pooled_conversion_rate_weights_sessions_not_groups():
    groups = {"a": [session("a", 1, True)],
              "b": [session(str(i), 1, False) for i in range(3)], "empty": []}
    assert pooled_conversion_rate(groups) == 0.25
    assert pooled_conversion_rate({"empty": []}) == 0.0
    assert pooled_conversion_rate({}) == 0.0


@pytest.mark.parametrize("days, expected", [(0, 0), (1, 3), (2, 5), (3, 6), (8, 6)])
def test_conversions_in_window(days, expected):
    assert conversions_in_window [ ] if False else conversions_in_window([1, 2, 3], days) == expected


def test_parse_session_log_skips_and_strips_and_parses_all_flags():
    lines = ["", "  \t", "  # comment,ignored,1", " a , -2 , 1 ",
             "b, 0, 0", " c, 3,   "]
    assert parse_session_log(iter(lines)) == [
        session("a", -2, True), session("b", 0, False), session("c", 3, None)
    ]


@pytest.mark.parametrize("bad", ["a,1", "a,1,0,extra", "a,no,1", "a,1,yes"])
def test_parse_session_log_reports_input_line_number(bad):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_session_log(["# comment", "", "valid,0,1", bad])


def test_dedupe_sessions_keeps_last_duplicate_and_sorts_by_day_then_id():
    first = session("a", 0, True)
    replacement = session("a", 2, None)
    events = [first, session("z", 1, True), session("b", 2, False), replacement]
    assert dedupe_sessions(events) == [events[1], replacement, events[2]]
    assert dedupe_sessions([]) == []


def test_daily_conversion_counts_include_empty_days_and_ignore_outside_range():
    events = [session("a", 1, True), session("b", 1, True),
              session("c", 2, None), session("d", 3, False),
              session("e", 4, True), session("f", 0, True)]
    assert daily_conversion_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_conversion_counts([], 1, 3) == [0, 0, 0]
    assert daily_conversion_counts(events, 4, 3) == []


def test_campaign_summary_uses_calendar_days_and_pooled_rate():
    groups = {"a": [session("a", 1, True)],
              "b": [session("b", 2, True), session("c", 4, False)], "empty": []}
    assert campaign_summary(groups, 2) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert campaign_summary(groups, 3)["recent"] == 1
    assert campaign_summary(groups, 0)["recent"] == 0
    assert campaign_summary({"empty": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert campaign_summary({}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_converting_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {"z": [session("z", 1, True)], "empty": [],
              "a": [session("a", 1, True)], "b": [session("b", 1, False)]}
    assert top_converting_groups(groups, 9) == ["a", "z", "b"]
    assert top_converting_groups(groups, 1) == ["a"]
    assert top_converting_groups(groups, 0) == []


def test_conversion_rate_by_group_sorted_and_empty_is_none():
    groups = {"z": [], "c": [session("c", 1, False)], "a": [session("a", 1, True)]}
    result = conversion_rate_by_group(groups)
    assert list(result) == ["a", "c", "z"]
    assert result == {"a": 1.0, "c": 0.0, "z": None}


@pytest.mark.parametrize("counts, expected", [([], 0), ([0, -1, 0], 0),
                                               ([1, 2, 0, 3, 4, 5], 3),
                                               ([1, -1, 1], 1)])
def test_longest_conversion_streak(counts, expected):
